insert into public.assessment_questions (kind, lesson_id, unit_id, course_id, prompt, choices, correct_choice_id, hint, order_index, is_reserve) values
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "Applying least privilege to vendor access in supply chain security reflects a principle used where else in this course?"}', '[{"id": "a", "text": {"en": "Only in wireless security"}}, {"id": "b", "text": {"en": "Only in cryptography"}}, {"id": "c", "text": {"en": "Nowhere else; it''s unique to vendors"}}, {"id": "d", "text": {"en": "Cloud IAM, Kubernetes RBAC, and Zero Trust access decisions alike"}}]', 'd', null, 1, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "Endpoint hardening is primarily about:"}', '[{"id": "a", "text": {"en": "Reducing the number of ways an endpoint can actually be attacked"}}, {"id": "b", "text": {"en": "Making an endpoint run faster"}}, {"id": "c", "text": {"en": "Adding more installed software"}}, {"id": "d", "text": {"en": "Increasing the attack surface deliberately"}}]', 'a', null, 2, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "Business Continuity and Disaster Recovery are best understood as which concept, scaled to an organization-wide event?"}', '[{"id": "a", "text": {"en": "The Recovery phase of the Incident Response lifecycle"}}, {"id": "b", "text": {"en": "SQL injection prevention"}}, {"id": "c", "text": {"en": "Digital signature verification"}}, {"id": "d", "text": {"en": "MITRE ATT&CK tactics"}}]', 'a', null, 3, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "A digital certificate is issued by:"}', '[{"id": "a", "text": {"en": "The website owner alone"}}, {"id": "b", "text": {"en": "Your internet service provider"}}, {"id": "c", "text": {"en": "A trusted third party called a Certificate Authority"}}, {"id": "d", "text": {"en": "Your antivirus software"}}]', 'c', null, 4, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "Third-party risk refers to:"}', '[{"id": "a", "text": {"en": "The security exposure introduced by every vendor, contractor, and service provider connected to your systems"}}, {"id": "b", "text": {"en": "Risk that only exists within your own organization"}}, {"id": "c", "text": {"en": "A type of firewall"}}, {"id": "d", "text": {"en": "A risk that never actually matters in practice"}}]', 'a', null, 5, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "The principle of least privilege means:"}', '[{"id": "a", "text": {"en": "Giving every user full administrative access"}}, {"id": "b", "text": {"en": "Removing access from everyone equally"}}, {"id": "c", "text": {"en": "Giving users only the access they actually need to do their job"}}, {"id": "d", "text": {"en": "Sharing one login across a whole team"}}]', 'c', null, 6, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "Which of these is the most realistic form of BC/DR testing?"}', '[{"id": "a", "text": {"en": "Never testing at all"}}, {"id": "b", "text": {"en": "A full simulation, actually failing over and restoring from real backups"}}, {"id": "c", "text": {"en": "Only reading the plan once"}}, {"id": "d", "text": {"en": "Guessing what might happen"}}]', 'b', null, 7, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "Traditional signature-based antivirus has an obvious blind spot:"}', '[{"id": "a", "text": {"en": "It works perfectly against everything"}}, {"id": "b", "text": {"en": "It requires no updates ever"}}, {"id": "c", "text": {"en": "It''s too fast to be useful"}}, {"id": "d", "text": {"en": "It can only catch threats it already recognizes from its signature database"}}]', 'd', null, 8, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "A SOC Analyst primarily focuses on:"}', '[{"id": "a", "text": {"en": "Designing overall security architecture"}}, {"id": "b", "text": {"en": "Authorized attacks to find vulnerabilities"}}, {"id": "c", "text": {"en": "Legal compliance frameworks exclusively"}}, {"id": "d", "text": {"en": "Frontline monitoring, investigating alerts, and escalating incidents"}}]', 'd', null, 9, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "Digital forensics is best described as:"}', '[{"id": "a", "text": {"en": "Randomly guessing what happened"}}, {"id": "b", "text": {"en": "Properly collecting, preserving, and analyzing digital evidence after an incident"}}, {"id": "c", "text": {"en": "Deleting compromised systems immediately"}}, {"id": "d", "text": {"en": "A casual review with no documentation"}}]', 'b', null, 10, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "A flashlight app requesting access to your contacts and location is:"}', '[{"id": "a", "text": {"en": "A red flag, since it has no real technical need for that access"}}, {"id": "b", "text": {"en": "A completely normal technical requirement"}}, {"id": "c", "text": {"en": "Required by every app store"}}, {"id": "d", "text": {"en": "A sign the app is well-designed"}}]', 'a', null, 11, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "An exploit is:"}', '[{"id": "a", "text": {"en": "A type of firewall"}}, {"id": "b", "text": {"en": "A password policy"}}, {"id": "c", "text": {"en": "A piece of code or technique that takes advantage of a specific vulnerability"}}, {"id": "d", "text": {"en": "A backup strategy"}}]', 'c', null, 12, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "Chain of custody is:"}', '[{"id": "a", "text": {"en": "A documented, unbroken record of who handled evidence, when, and what they did with it"}}, {"id": "b", "text": {"en": "A type of firewall"}}, {"id": "c", "text": {"en": "A backup strategy"}}, {"id": "d", "text": {"en": "An encryption method"}}]', 'a', null, 13, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "CompTIA Security+ is best described as:"}', '[{"id": "a", "text": {"en": "A senior-level, highly specialized certification"}}, {"id": "b", "text": {"en": "An entry-level certification validating foundational knowledge"}}, {"id": "c", "text": {"en": "Exclusively for penetration testers"}}, {"id": "d", "text": {"en": "A physical security credential"}}]', 'b', null, 14, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "Data poisoning is:"}', '[{"id": "a", "text": {"en": "A physical attack on server hardware"}}, {"id": "b", "text": {"en": "An attack where corrupted or misleading data is deliberately introduced to influence what a model learns"}}, {"id": "c", "text": {"en": "A type of firewall rule"}}, {"id": "d", "text": {"en": "A backup corruption issue only"}}]', 'b', null, 15, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "Network segmentation is the practice of:"}', '[{"id": "a", "text": {"en": "Merging all devices onto one shared network"}}, {"id": "b", "text": {"en": "Disabling the internet entirely"}}, {"id": "c", "text": {"en": "Deleting old network logs"}}, {"id": "d", "text": {"en": "Splitting a network into separate zones to limit how far a breach can spread"}}]', 'd', null, 16, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "Logs are:"}', '[{"id": "a", "text": {"en": "A type of encryption"}}, {"id": "b", "text": {"en": "Physical evidence only"}}, {"id": "c", "text": {"en": "Records that applications and systems automatically keep of events"}}, {"id": "d", "text": {"en": "Something that''s always immediately deleted"}}]', 'c', null, 17, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "Microsegmentation, compared to traditional network segmentation, is:"}', '[{"id": "a", "text": {"en": "Exactly the same thing with a different name"}}, {"id": "b", "text": {"en": "Broader and less specific"}}, {"id": "c", "text": {"en": "Far more fine-grained, sometimes down to individual applications or workloads"}}, {"id": "d", "text": {"en": "Focused only on physical hardware"}}]', 'c', null, 18, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "Bluesnarfing is considered dangerous because it can:"}', '[{"id": "a", "text": {"en": "Only send harmless messages"}}, {"id": "b", "text": {"en": "Let an attacker access data like contacts and files without permission"}}, {"id": "c", "text": {"en": "Require the victim''s explicit consent first"}}, {"id": "d", "text": {"en": "Only affect devices with Bluetooth turned off"}}]', 'b', null, 19, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "Anomaly detection using AI in cybersecurity works by:"}', '[{"id": "a", "text": {"en": "Randomly flagging activity with no learning involved"}}, {"id": "b", "text": {"en": "Only detecting physical hardware failures"}}, {"id": "c", "text": {"en": "Learning what \"normal\" activity looks like and flagging genuine deviations from it"}}, {"id": "d", "text": {"en": "Replacing the need for any human analyst entirely"}}]', 'c', null, 20, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "TCP/IP functions as:"}', '[{"id": "a", "text": {"en": "A single company''s proprietary software"}}, {"id": "b", "text": {"en": "A type of malware"}}, {"id": "c", "text": {"en": "A shared set of rules that lets different devices communicate"}}, {"id": "d", "text": {"en": "A physical cable standard"}}]', 'c', null, 21, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "In the shared responsibility model, the cloud provider is generally responsible for:"}', '[{"id": "a", "text": {"en": "Your specific data and configurations"}}, {"id": "b", "text": {"en": "The physical infrastructure and underlying hardware"}}, {"id": "c", "text": {"en": "Nothing at all"}}, {"id": "d", "text": {"en": "Your personal passwords"}}]', 'b', null, 22, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "GDPR is:"}', '[{"id": "a", "text": {"en": "A European Union regulation with legal force and financial penalties for violations"}}, {"id": "b", "text": {"en": "An optional guideline with no legal weight"}}, {"id": "c", "text": {"en": "A certification for individual security professionals"}}, {"id": "d", "text": {"en": "A framework specific to the United States only"}}]', 'a', null, 23, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "Risk is typically thought of as:"}', '[{"id": "a", "text": {"en": "Impact alone"}}, {"id": "b", "text": {"en": "A random guess"}}, {"id": "c", "text": {"en": "Likelihood alone"}}, {"id": "d", "text": {"en": "Likelihood multiplied by impact"}}]', 'd', null, 24, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "A commonly recommended way to build practical cybersecurity skill is to:"}', '[{"id": "a", "text": {"en": "Practice on legal platforms designed for this, like TryHackMe or HackTheBox"}}, {"id": "b", "text": {"en": "Avoid any hands-on practice entirely"}}, {"id": "c", "text": {"en": "Only read certification study guides"}}, {"id": "d", "text": {"en": "Wait until landing a job to learn anything practical"}}]', 'a', null, 25, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "Containers, unlike traditional virtual machines, typically:"}', '[{"id": "a", "text": {"en": "Share the underlying operating system kernel with other containers"}}, {"id": "b", "text": {"en": "Each run a completely separate operating system"}}, {"id": "c", "text": {"en": "Are always slower to start than VMs"}}, {"id": "d", "text": {"en": "Have no security considerations at all"}}]', 'a', null, 26, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "Compromising the Kubernetes control plane can potentially give an attacker:"}', '[{"id": "a", "text": {"en": "Access to nothing significant"}}, {"id": "b", "text": {"en": "Only cosmetic changes to a dashboard"}}, {"id": "c", "text": {"en": "Control over the entire cluster and everything running on it"}}, {"id": "d", "text": {"en": "Access to a single, isolated container only"}}]', 'c', null, 27, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "A SIEM system primarily:"}', '[{"id": "a", "text": {"en": "Physically blocks network traffic"}}, {"id": "b", "text": {"en": "Only stores backups"}}, {"id": "c", "text": {"en": "Replaces the need for any human analyst entirely"}}, {"id": "d", "text": {"en": "Centralizes logs from across an environment and correlates them to surface what matters"}}]', 'd', null, 28, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "WEP, as a wifi security standard, is now considered:"}', '[{"id": "a", "text": {"en": "The most secure option available"}}, {"id": "b", "text": {"en": "Equivalent to WPA3"}}, {"id": "c", "text": {"en": "Impossible to crack"}}, {"id": "d", "text": {"en": "Badly broken and crackable by freely available tools"}}]', 'd', null, 29, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "The Secure Development Lifecycle (SDLC) treats security as:"}', '[{"id": "a", "text": {"en": "Something only relevant after a breach occurs"}}, {"id": "b", "text": {"en": "A task exclusively for the testing team"}}, {"id": "c", "text": {"en": "A thread running through every stage of development, not just a final step"}}, {"id": "d", "text": {"en": "An optional add-on for large companies only"}}]', 'c', null, 30, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "Prompt injection in AI systems shares its core underlying logic with which earlier vulnerability pattern?"}', '[{"id": "a", "text": {"en": "WEP''s outdated encryption"}}, {"id": "b", "text": {"en": "A weak password"}}, {"id": "c", "text": {"en": "A physical security bypass"}}, {"id": "d", "text": {"en": "SQL injection - untrusted input being treated as executable instructions instead of plain data"}}]', 'd', null, 31, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "Passive reconnaissance involves:"}', '[{"id": "a", "text": {"en": "Directly hacking into a system"}}, {"id": "b", "text": {"en": "Gathering information without directly interacting with the target''s systems"}}, {"id": "c", "text": {"en": "Only reading company financial reports"}}, {"id": "d", "text": {"en": "Sending malware to the target"}}]', 'b', null, 32, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "A Software Bill of Materials (SBOM) is:"}', '[{"id": "a", "text": {"en": "A financial invoice for software purchases"}}, {"id": "b", "text": {"en": "A type of firewall"}}, {"id": "c", "text": {"en": "A backup schedule"}}, {"id": "d", "text": {"en": "A detailed inventory of every component, library, and dependency that makes up an application"}}]', 'd', null, 33, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "The core principle of Zero Trust is:"}', '[{"id": "a", "text": {"en": "Trusting all internal network traffic by default"}}, {"id": "b", "text": {"en": "Never trusting any user, device, or system by default, regardless of location"}}, {"id": "c", "text": {"en": "Building one extremely strong perimeter firewall"}}, {"id": "d", "text": {"en": "Eliminating the need for authentication"}}]', 'b', null, 34, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "The OWASP Top 10 is best described as:"}', '[{"id": "a", "text": {"en": "A list of the fastest websites"}}, {"id": "b", "text": {"en": "A programming language"}}, {"id": "c", "text": {"en": "A type of firewall"}}, {"id": "d", "text": {"en": "The industry''s go-to list of the most critical web application security risks"}}]', 'd', null, 35, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "Why does EDR''s detailed activity logging matter for a later investigation, connecting endpoint security to digital forensics?"}', '[{"id": "a", "text": {"en": "It has no connection to forensics at all"}}, {"id": "b", "text": {"en": "EDR logs are always deleted immediately"}}, {"id": "c", "text": {"en": "It provides exactly the kind of evidence a forensic investigation depends on"}}, {"id": "d", "text": {"en": "Forensics never uses endpoint data"}}]', 'c', null, 36, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "What causes the majority of cloud security incidents?"}', '[{"id": "a", "text": {"en": "Sophisticated technical exploits exclusively"}}, {"id": "b", "text": {"en": "Simple misconfigurations, like storage left publicly accessible"}}, {"id": "c", "text": {"en": "Hardware failures"}}, {"id": "d", "text": {"en": "Weather-related outages"}}]', 'b', null, 37, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "EDR stands for:"}', '[{"id": "a", "text": {"en": "Extended Data Retrieval"}}, {"id": "b", "text": {"en": "Endpoint Detection and Response"}}, {"id": "c", "text": {"en": "External Device Restriction"}}, {"id": "d", "text": {"en": "Encrypted Data Router"}}]', 'b', null, 38, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "Recovery Time Objective (RTO) measures:"}', '[{"id": "a", "text": {"en": "How much data can be lost"}}, {"id": "b", "text": {"en": "The cost of a backup solution"}}, {"id": "c", "text": {"en": "The number of employees affected"}}, {"id": "d", "text": {"en": "How long a system can realistically be down before impact becomes unacceptable"}}]', 'd', null, 39, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "CSRF tricks a victim''s browser into:"}', '[{"id": "a", "text": {"en": "Sending an unintended request to a site they''re already logged into"}}, {"id": "b", "text": {"en": "Permanently deleting their account"}}, {"id": "c", "text": {"en": "Encrypting their session token"}}, {"id": "d", "text": {"en": "Blocking their internet access"}}]', 'a', null, 40, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "How does Zero Trust''s microsegmentation extend the network segmentation concept from Unit 1?"}', '[{"id": "a", "text": {"en": "By making segmentation broader and less specific"}}, {"id": "b", "text": {"en": "They are entirely unrelated concepts"}}, {"id": "c", "text": {"en": "By applying the same containment logic at a much finer, more granular level"}}, {"id": "d", "text": {"en": "By eliminating the need for any segmentation at all"}}]', 'c', null, 41, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "Across all sixteen units of this course, which idea has been reinforced most consistently?"}', '[{"id": "a", "text": {"en": "Technology changes, but understanding mechanisms, anticipating misuse, and layering defenses stays useful throughout"}}, {"id": "b", "text": {"en": "Every threat requires a completely unique, unrelated defense"}}, {"id": "c", "text": {"en": "Only the newest tools matter"}}, {"id": "d", "text": {"en": "Security is entirely the responsibility of one specialized team"}}]', 'a', null, 42, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "A security policy is:"}', '[{"id": "a", "text": {"en": "A type of firewall"}}, {"id": "b", "text": {"en": "Only relevant to IT staff"}}, {"id": "c", "text": {"en": "A formal document defining an organization''s security rules and expectations"}}, {"id": "d", "text": {"en": "An optional suggestion with no real weight"}}]', 'c', null, 43, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "A compromised CI/CD pipeline is best understood as an example of:"}', '[{"id": "a", "text": {"en": "A wireless security misconfiguration"}}, {"id": "b", "text": {"en": "A software supply chain attack, since it can inject malicious code that ships to every downstream user"}}, {"id": "c", "text": {"en": "A GDPR violation exclusively"}}, {"id": "d", "text": {"en": "A digital forensics failure"}}]', 'b', null, 44, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "A CI/CD pipeline is:"}', '[{"id": "a", "text": {"en": "A type of firewall"}}, {"id": "b", "text": {"en": "An automated process that builds, tests, and deploys code, often with minimal human involvement"}}, {"id": "c", "text": {"en": "A physical network cable"}}, {"id": "d", "text": {"en": "A password policy"}}]', 'b', null, 45, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "In a DNS spoofing attack, the attacker:"}', '[{"id": "a", "text": {"en": "Feeds false information to a DNS server to redirect victims to a fake site"}}, {"id": "b", "text": {"en": "Physically damages a router"}}, {"id": "c", "text": {"en": "Deletes a victim''s files"}}, {"id": "d", "text": {"en": "Strengthens DNS security"}}]', 'a', null, 46, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "The TLS handshake happens:"}', '[{"id": "a", "text": {"en": "Automatically, every time you connect to an HTTPS site"}}, {"id": "b", "text": {"en": "Only once per year"}}, {"id": "c", "text": {"en": "Manually, initiated by the user"}}, {"id": "d", "text": {"en": "Only when there''s an error"}}]', 'a', null, 47, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "A software supply chain attack typically involves:"}', '[{"id": "a", "text": {"en": "Attacking thousands of individual targets one at a time directly"}}, {"id": "b", "text": {"en": "No trust relationship at all"}}, {"id": "c", "text": {"en": "Compromising a single trusted piece of software that many organizations then willingly install"}}, {"id": "d", "text": {"en": "Only physical theft of hardware"}}]', 'c', null, 48, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "Business Continuity (BC) primarily focuses on:"}', '[{"id": "a", "text": {"en": "Restoring IT systems after a disruption"}}, {"id": "b", "text": {"en": "Preventing every possible disruption completely"}}, {"id": "c", "text": {"en": "Keeping critical business functions running during a disruption"}}, {"id": "d", "text": {"en": "Only IT-specific recovery tasks"}}]', 'c', null, 49, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "Prompt injection is best understood as:"}', '[{"id": "a", "text": {"en": "The AI-era equivalent of injection attacks, where hidden instructions get embedded in content an AI processes"}}, {"id": "b", "text": {"en": "A type of network firewall"}}, {"id": "c", "text": {"en": "A backup strategy for AI systems"}}, {"id": "d", "text": {"en": "A password policy specific to AI tools"}}]', 'a', null, 50, false),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "Continuous verification means:"}', '[{"id": "a", "text": {"en": "Checking identity only once at login"}}, {"id": "b", "text": {"en": "Never checking any signals after initial login"}}, {"id": "c", "text": {"en": "Only checking passwords, nothing else"}}, {"id": "d", "text": {"en": "Access decisions get reevaluated repeatedly throughout a session"}}]', 'd', null, 51, true),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "The most valuable deliverable of a penetration test is often:"}', '[{"id": "a", "text": {"en": "The exploit code itself"}}, {"id": "b", "text": {"en": "A list of every employee''s name"}}, {"id": "c", "text": {"en": "A new firewall"}}, {"id": "d", "text": {"en": "The report"}}]', 'd', null, 52, true),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "PKI is:"}', '[{"id": "a", "text": {"en": "A single company"}}, {"id": "b", "text": {"en": "A type of firewall"}}, {"id": "c", "text": {"en": "A password manager"}}, {"id": "d", "text": {"en": "The entire framework of trust that makes certificate-based verification work"}}]', 'd', null, 53, true),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "A SOC is:"}', '[{"id": "a", "text": {"en": "A type of firewall"}}, {"id": "b", "text": {"en": "The team responsible for continuously monitoring, detecting, and responding to security threats"}}, {"id": "c", "text": {"en": "A single automated tool"}}, {"id": "d", "text": {"en": "A physical building only"}}]', 'b', null, 54, true),
  ('final_exam', null, null, '2aac732f-bf20-491c-9128-2afdbc056d7c', '{"en": "MITRE ATT&CK is best described as:"}', '[{"id": "a", "text": {"en": "A structured knowledge base of real-world attacker tactics and techniques"}}, {"id": "b", "text": {"en": "A single antivirus product"}}, {"id": "c", "text": {"en": "A type of encryption standard"}}, {"id": "d", "text": {"en": "A physical security device"}}]', 'a', null, 55, true);
